syntax = "proto3";

package lab;

// The cloud reaches every on-prem client through one proxy call: which client, which method, and the request as bytes.
service AgentProxy {
  rpc AgentRpc(AgentRpcRequest) returns (AgentRpcResponse);
}

message AgentRpcRequest {
  string agent_id = 1;
  string method_name = 2;
  bytes request_data = 3;
}

message AgentRpcResponse {
  enum ErrorType {
    NONE = 0;
    TIMEOUT = 1;
  }
  bytes response_data = 1;
  string error_message = 2;
  ErrorType error_type = 3;
}

// The methods an on-prem client offers. Their requests travel inside request_data.
service Agent {
  rpc HealthCheck(HealthCheckRequest) returns (HealthCheckResponse);
  rpc ScheduleTask(ScheduleTaskRequest) returns (Empty);
}

message HealthCheckRequest {}
message HealthCheckResponse {
  bool is_healthy = 1;
}
message ScheduleTaskRequest {
  string task_uid = 1;
  string task_type = 2;
  string dataset_uid = 3;
}
message Empty {}
EOF
