"""The cloud's client for on-prem agents. Production code; tests must not replace it."""
import os

import grpc

import agent_pb2 as pb
from agent_pb2_grpc import AgentProxyStub


class AgentOffline(Exception):
    pass


class AgentClient:
    def __init__(self):
        self.stub = AgentProxyStub(grpc.insecure_channel(os.environ["AGENT_PROXY_ADDRESS"]))  # read on every new client

    def call(self, agent_id, method, request, response_type):
        reply = self.stub.AgentRpc(
            pb.AgentRpcRequest(agent_id=agent_id, method_name=method, request_data=request.SerializeToString())
        )
        if reply.error_type == pb.AgentRpcResponse.TIMEOUT:
            raise AgentOffline(agent_id)
        if reply.error_message:
            raise RuntimeError(reply.error_message)
        return response_type.FromString(reply.response_data)
EOF
