"""Cloud code under test: what the projects page shows about each site's on-prem agent."""
import agent_pb2 as pb
from agent_client import AgentClient, AgentOffline


def site_status(agent_id: str) -> str:
    try:
        health = AgentClient().call(agent_id, "HealthCheck", pb.HealthCheckRequest(), pb.HealthCheckResponse)
    except AgentOffline:
        return "offline"
    return "ready" if health["is_healthy"] else "unhealthy"
EOF

